add_shortcode( 'copyright_year', 'perfectpixel_copyright_year_shortcode' );

function perfectpixel_copyright_year_shortcode( $atts ) {
	$atts = shortcode_atts( array( 'from' => '', 'site' => 'no' ), $atts, 'copyright_year' );
	$year = (int) wp_date( 'Y' );
	$from = (int) $atts['from'];
	$text = '© ' . ( ( $from && $from < $year ) ? $from . '–' . $year : $year );
	if ( 'yes' === strtolower( $atts['site'] ) ) {
		$text .= ' ' . wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES );
	}
	return '<span class="perfectpixel-copyright">' . esc_html( $text ) . '</span>';
}
